use crate::http::open_api::OpenApiDocument;

/// Metadata generated by `#[wtx::openapi]`.
#[derive(Debug)]
pub struct OpenApiHandler {
  /// Component registration functions.
  pub components: &'static [fn(&mut OpenApiDocument)],
  /// Long description.
  pub description: Option<&'static str>,
  /// Operation identifier.
  pub operation_id: &'static str,
  /// Parameters inferred from the handler signature.
  pub parameters: &'static [OpenApiHandlerParameterMeta],
  /// Request body.
  pub request_body: Option<OpenApiHandlerRequestBodyMeta>,
  /// Responses.
  pub responses: &'static [OpenApiHandlerResponseMeta],
  /// Short summary.
  pub summary: Option<&'static str>,
  /// Tags.
  pub tags: &'static [&'static str],
}

/// Parameter metadata.
#[derive(Debug)]
pub struct OpenApiHandlerParameterMeta {
  /// Description.
  pub description: Option<&'static str>,
  /// Location.
  pub location: &'static str,
  /// Name.
  pub name: &'static str,
  /// Whether the parameter is required.
  pub required: bool,
  /// Schema.
  pub schema: OpenApiHandlerSchemaMeta,
}

/// Request body metadata.
#[derive(Debug)]
pub struct OpenApiHandlerRequestBodyMeta {
  /// Content type
  pub content_type: &'static str,
  /// Whether the body is required.
  pub required: bool,
  /// Schema.
  pub schema: OpenApiHandlerSchemaMeta,
}

/// Response metadata.
#[derive(Debug)]
pub struct OpenApiHandlerResponseMeta {
  /// Media type, if a body exists.
  pub content_type: Option<&'static str>,
  /// Description.
  pub description: &'static str,
  /// Schema, if a body exists.
  pub schema: Option<OpenApiHandlerSchemaMeta>,
  /// Status code or `default`.
  pub status: &'static str,
}

/// A schema expression that can be built in a `static`.
#[derive(Debug, Clone, Copy)]
pub enum OpenApiHandlerSchemaMeta {
  /// Array.
  Array(&'static OpenApiHandlerSchemaMeta),
  /// Boolean.
  Bool,
  /// Integer with an optional format.
  Integer(Option<&'static str>),
  /// Nullable version of the inner schema.
  Nullable(&'static OpenApiHandlerSchemaMeta),
  /// Floating point number.
  Number,
  /// Reference to a named component.
  Ref(&'static str),
  /// Vector.
  Vector,
}
